ity_priest_pathofthedevout:20|t%s commence à lancer |cFFFF0000|Hspell:244509|h[Sororité des Sargereï]|h|r.','|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s commence à lancer |cFFFF0000|Hspell:244509|h[Sororité des Sargereï]|h|r.',26124),(131545,'enUS','Ugh...','',26124),(131545,'frFR','Beurk…','',26124),(131546,'enUS','Help...','',26124),(131546,'frFR','Au secours…','',26124),(131547,'enUS','Please help.','',26124),(131547,'frFR','Vous aidez, s’il vous plaît.','',26124),(131548,'enUS','Help me.','',26124),(131548,'frFR','Aidez-moi.','',26124),(131549,'enUS','...','',26124),(131549,'frFR','…','',26124),(131550,'enUS','Administer the antidote.','Administer the antidote.',26124),(131550,'frFR','Administrer l’antidote.','Administrer l’antidote.',26124),(131551,'enUS','<The moonkin hatchling seems to be very happy with you.>','',26124),(131551,'frFR','<Le bébé sélénien semble ravi de vous voir.>','',26124),(131552,'enUS','I love you.','',26124),(131552,'frFR','Je vous aime.','',26124),(131553,'enUS','Thank you!','',26124),(131553,'frFR','Merci !','',26124),(131554,'enUS','Yay!','',26124),(131554,'frFR','Ouais !','',26124),(131555,'enUS','Hooray!','',26124),(131555,'frFR','Hourra !','',26124),(131556,'enUS','You are amazing.','',26124),(131556,'frFR','Vous êtes formidable.','',26124),(131557,'enUS','You are the best!','',26124),(131557,'frFR','Vous êtes $gle meilleur:la meilleure; !','',26124),(131559,'enUS','Jadefire have antidote!','',26124),(131559,'frFR','Jadefeu a antidote !','',26124),(131561,'enUS','Help Clookle!','',26124),(131561,'frFR','Aidez Clouklou !','',26124),(131563,'enUS','Find Clookle!','',26124),(131563,'frFR','Trouvez Clouklou !','',26124),(131564,'enUS','Save Clookle!','',26124),(131564,'frFR','Sauvez Clouklou !','',26124),(131565,'enUS','Clookle underground!','',26124),(131565,'frFR','Clouklou sous terre !','',26124),(131566,'enUS','Kill Jadefire!','',26124),(131566,'frFR','Tuez Jadefeu !','',26124),(131567,'enUS','Thank you.','',26124),(1