INSERT INTO `mount` VALUES ('Magmatic hound','Previously these dogs used for tracking and killing. But later they became also riding animals.','Reward for  New Year Event.',305002,0,230,0,2,5000,0,45,1),('Tarecgosa\'s Visage','Transforms you into Tarecgosa\'s Visage, allowing you to fly very fast.','Special server rewards',101641,0,248,64,1,5001,0,4,0),('Magic Broom',NULL,NULL,47977,0,248,64,1,5002,0,0,0),('Affected Abyss Bird of Fire','After the connection with the abyss, the rage of these birds became even more...','Special Project Awards',305184,0,230,0,2,5010,0,4,0),('Blue Phoenix','Birds of unprecedented beauty.','Special Project Awards',305185,0,248,0,2,5011,0,4,0),('Lilac Phoenix','Birds of unprecedented beauty.','Special Project Awards',305186,0,248,0,2,5012,0,4,0),('Blazing phoenix','Birds of unprecedented beauty.','Special Project Awards',305187,0,248,0,2,5013,0,4,0),('Provinces of Bad Claws','The Blazing Legion has experimented with the desecration of many animal species. Including fire birds from volcanic worlds.','Special Project Awards',305188,0,230,0,2,5014,0,4,0),('Xuen child','Do you like cats?','Special Project Awards',305189,0,230,0,2,5015,0,4,0),('The LokÃƒÂ©\'nahak Provinces','Do you like cats?','Special Project Awards',305190,0,230,0,2,5016,0,4,0),('Illidari Badger','Illidari\'s tame badass. It\'s terrible, but you can walk.','Special Project Awards',305191,0,248,0,2,5017,0,4,0),('Phantom hippogriff','Causes the Hippogriff\'s Spirit.','Special Project Awards',305192,0,248,0,2,5018,0,4,0),('Kul-Tiras Horse','Kul-Tiras horses are tamed from an early age not to be afraid of the sea and are raced along the coast in a myriad of salty splashes.','Special Project Awards',305193,0,230,0,2,5019,0,4,0),('Zuldazar\'s Lizard','A means of transportation to become High Priests and Zandalari Elders, adorned with exquisite harness and blessed by Rezan, the greatest of the devils.','Special Project Awards',305194,0,230,0,2,5020,0,4,0),('Shu-tsen, Divine Guardian.','While the Golden Lotus pandarans struggled to restore the Eternal Blossoming Dol, one statue came to life and silently protected them from Shah attacks. Some consider Shu-tsen a symbol of luck, others a gift of light. He will be a faithful companion to any hero who dares to defend Azeroth from the mad whispering of the ancient gods.','Special Project Awards',305195,0,248,0,2,5021,0,4,0),('Somber Dawn','','New Year event 2019',305286,0,230,0,2,5022,0,4,0),('Red Illidari Felbat','','New Year event 2019',305288,0,248,0,2,5023,0,4,0),('Tarecgosa\'s Visage','The power of staff doesn\'t need anymore. You can transform into Tarecgosa anytime.','Special project rewards',305297,0,248,0,2,5025,0,4,0);
/*!40000 ALTER TABLE `mount` ENABLE KEYS */;
